package org.example.spotifymixer.runtime;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class QueueClearSessionTest {
 static class Backend implements QueueClearSession.Backend {int writes,revision=1;boolean refill,fail;List<String> next=new ArrayList<>(Arrays.asList("A","B"));public QueueClearSession.Snapshot read(){return new QueueClearSession.Snapshot(""+revision,"current",next,Collections.singletonList("previous"),null);}public void clear(QueueClearSession.Snapshot s)throws Exception{writes++;revision++;if(!refill)next.clear();if(fail)throw new java.io.IOException("uncertain");}}
 static class Recovery implements QueueClearSession.Recovery {String value;List<String> previous;public String pending(){return value;}public void begin(String s){value=s;}public void begin(QueueClearSession.Snapshot s){value=s.current;previous=s.previous;}public List<String> previous(){return previous;}public void complete(){value=null;}}
 @Test public void oneRevisionBoundWriteAndReadback()throws Exception{Backend b=new Backend();Recovery r=new Recovery();QueueClearSession s=new QueueClearSession(b,r);QueueClearSession.Snapshot p=s.preview();s.clear(p);assertEquals(1,b.writes);assertNull(r.value);assertTrue(b.next.isEmpty());try{s.clear(p);fail();}catch(java.io.IOException expected){}assertEquals(1,b.writes);}
 @Test public void staleRevisionNeverWrites()throws Exception{Backend b=new Backend();Recovery r=new Recovery();QueueClearSession s=new QueueClearSession(b,r);QueueClearSession.Snapshot p=s.preview();b.revision++;try{s.clear(p);fail();}catch(java.io.IOException expected){}assertEquals(0,b.writes);assertNull(r.value);}
 @Test public void sameRevisionWithChangedItemsNeverWrites()throws Exception{Backend b=new Backend();Recovery r=new Recovery();QueueClearSession s=new QueueClearSession(b,r);QueueClearSession.Snapshot p=s.preview();b.next.add("changed");try{s.clear(p);fail();}catch(java.io.IOException expected){}assertEquals(0,b.writes);assertNull(r.value);}
 @Test public void previousItemsMustBeVerifiedBeforeCompletingRecovery()throws Exception{Backend b=new Backend();Recovery r=new Recovery();QueueClearSession s=new QueueClearSession(b,r);b.next.clear();r.value="current";r.previous=Collections.singletonList("different");try{s.verify();fail();}catch(java.io.IOException expected){}assertNotNull(r.value);assertEquals(0,b.writes);}
 @Test public void uncertainWriteLeavesRecoveryAndOnlyVerifies()throws Exception{Backend b=new Backend();b.fail=true;Recovery r=new Recovery();QueueClearSession s=new QueueClearSession(b,r);try{s.clear(s.preview());fail();}catch(java.io.IOException expected){}assertNotNull(r.value);try{s.preview();fail();}catch(java.io.IOException expected){}s.verify();assertNull(r.value);assertEquals(1,b.writes);}
 @Test public void refillIsNotFalselyReportedAsCleared()throws Exception{Backend b=new Backend();b.refill=true;Recovery r=new Recovery();QueueClearSession s=new QueueClearSession(b,r);try{s.clear(s.preview());fail();}catch(java.io.IOException expected){}assertNotNull(r.value);assertEquals(1,b.writes);try{s.verify();fail();}catch(java.io.IOException expected){}assertEquals(1,b.writes);}
}
